import React from 'react';
import { Link } from 'react-router-dom';
import { Minus, Plus, Trash2, ShoppingBag } from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import './Cart.css';

export default function Cart() {
  const { cart, removeFromCart, updateQuantity, cartTotal } = useAuth();

  if (!cart.length) return (
    <div className="empty-cart">
      <ShoppingBag size={64} color="#FFB6C1" />
      <h2>Your cart is empty</h2>
      <p>Add some products to get started!</p>
      <Link to="/products" className="btn-primary">Start Shopping</Link>
    </div>
  );

  return (
    <div className="cart-page">
      <div className="container">
        <h1 className="page-title">Shopping Cart</h1>
        <div className="cart-layout">
          {/* Items */}
          <div className="cart-items">
            {cart.map(item => (
              <div key={item.id} className="cart-item">
                <img
                  src={item.image || `https://via.placeholder.com/100x100/FFB6C1/5C3D2E?text=${item.name}`}
                  alt={item.name}
                />
                <div className="item-info">
                  <h3>{item.name}</h3>
                  <p className="item-category">{item.category}</p>
                  <span className="item-price">₹{item.price}</span>
                </div>
                <div className="item-qty">
                  <button onClick={() => updateQuantity(item.id, item.quantity - 1)}><Minus size={14} /></button>
                  <span>{item.quantity}</span>
                  <button onClick={() => updateQuantity(item.id, item.quantity + 1)}><Plus size={14} /></button>
                </div>
                <div className="item-total">₹{(item.price * item.quantity).toFixed(2)}</div>
                <button className="remove-btn" onClick={() => removeFromCart(item.id)}>
                  <Trash2 size={16} />
                </button>
              </div>
            ))}
          </div>

          {/* Summary */}
          <div className="cart-summary">
            <h3>Order Summary</h3>
            <div className="summary-row"><span>Subtotal</span><span>₹{cartTotal.toFixed(2)}</span></div>
            <div className="summary-row"><span>Shipping</span><span>{cartTotal >= 499 ? 'Free' : '₹49'}</span></div>
            <div className="summary-row"><span>Tax (5%)</span><span>₹{(cartTotal * 0.05).toFixed(2)}</span></div>
            <div className="summary-divider" />
            <div className="summary-total">
              <span>Total</span>
              <span>₹{(cartTotal * 1.05 + (cartTotal >= 499 ? 0 : 49)).toFixed(2)}</span>
            </div>
            {cartTotal < 499 && (
              <p className="free-shipping-msg">Add ₹{(499 - cartTotal).toFixed(0)} more for free shipping!</p>
            )}
            <Link to="/checkout" className="btn-primary checkout-btn">Proceed to Checkout</Link>
            <Link to="/products" className="continue-shopping">← Continue Shopping</Link>
          </div>
        </div>
      </div>
    </div>
  );
}
